import{_ as e,o as t,c as a}from"./chunks/framework.D1Ss-Xl7.js";const g=JSON.parse('{"title":"Page 41 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"41","title":"Page 41 | Home","prev":"/page/40/","next":null,"posts":[{"title":"个人博客的建立","url":"/posts/2013-02-07-start-blog/","date":"2013-02-07 22:07","tags":["notes"],"html":"<p>好吧,我建立个人博客的想法其实已经差不多有一年了吧.一直没去实现...主要原因还是自己太懒...一开始想用 WordPress 搭建一个....其实我也搭建了\\n但是由于一直找不到好看的主题就坑在那一年多了...后来还想用 Octopress 来搭建...又由于自己当时的系统是 Win 而放弃了,现在我把自己的系统换成\\nArch 并且在学习 Python,于是又开坑了...</p>\\n<p>虽然是自己动手写出来的,但基本属于山寨,毕竟现在自己对 Python 的掌握还属于初级阶段...UI 其实也是山寨的 &gt;_&gt;</p>\\n<p>嘛嘛,先搭建出来一个再说,之后自己再慢慢装饰吧,不过总算是把坑给填上了.万事开头难,迈出了第一步,之后就容易多了....</p>\\n<p>不过我这个文笔很差的人写的博客估计也没人看</p>\\n"}]},"relativePath":"page/41/index.md","filePath":"page/[page].md"}'),p={name:"page/41/index.md"};function s(n,o,r,c,i,l){return t(),a("div")}const m=e(p,[["render",s]]);export{g as __pageData,m as default};
